import{_ as o,o as t,c as d,a3 as c}from"./chunks/framework.sni93WGf.js";const a="/blank/v2.1.0/screenshots/language.png",g=JSON.parse('{"title":"Autocorrect","description":"","frontmatter":{},"headers":[],"relativePath":"guide/autocorrect.md","filePath":"guide/autocorrect.md"}'),r={name:"guide/autocorrect.md"};function s(n,e,i,l,h,u){return t(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="autocorrect" tabindex="-1">Autocorrect <a class="header-anchor" href="#autocorrect" aria-label="Permalink to &quot;Autocorrect&quot;">​</a></h1><p>Blank corrects what you type the way Word and LibreOffice do. Most corrections apply once the word is complete: when you type Space, Tab, Enter or one of <code>. , ; : ? !</code> after it. <code>(c)</code>, <code>(r)</code> and <code>(tm)</code> turn into their symbol as soon as you type the <code>)</code>. All of this works anywhere in the text, not only at the end of a line.</p><ul><li><strong>Undo</strong> (<code>Mod</code> <code>Z</code>) reverts the last correction and keeps what you typed. That goes for block shortcuts too: one undo turns a new list or heading back into the <code>-</code> or <code>#</code> you typed.</li><li>Nothing is corrected inside code blocks or inline code.</li><li>Every group below can be <a href="./configuration#autocorrect">turned off</a>, and you can add your own replacements.</li></ul><h2 id="what-gets-corrected" tabindex="-1">What gets corrected <a class="header-anchor" href="#what-gets-corrected" aria-label="Permalink to &quot;What gets corrected&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You type</th><th>You get</th><th>Group</th></tr></thead><tbody><tr><td><code>--&gt;</code> <code>-&gt;</code> / <code>&lt;--</code> <code>&lt;-</code> / <code>&lt;--&gt;</code> <code>&lt;-&gt;</code></td><td>→ / ← / ↔</td><td><code>arrows</code></td></tr><tr><td><code>==&gt;</code> / <code>&lt;==</code> / <code>&lt;==&gt;</code></td><td>⇒ / ⇐ / ⇔</td><td><code>arrows</code></td></tr><tr><td><code>A - B</code>, <code>A -- B</code> / <code>A--B</code></td><td>A – B / A—B, the dashes of the language</td><td><code>dashes</code></td></tr><tr><td><code>(c)</code> <code>(r)</code> <code>(tm)</code> <code>...</code></td><td>© ® ™ …</td><td><code>symbols</code></td></tr><tr><td><code>1/2</code> <code>1/4</code> <code>3/4</code> <code>+-</code> <code>!=</code> <code>&lt;=</code> <code>&gt;=</code></td><td>½ ¼ ¾ ± ≠ ≤ ≥</td><td><code>symbols</code></td></tr><tr><td><code>**bold**</code> <code>*italic*</code> <code>_italic_</code> <code>`code`</code></td><td><strong>bold</strong> <em>italic</em> <em>italic</em> <code>code</code></td><td><code>formatting</code></td></tr><tr><td><code>[title](url)</code> / <code>![alt](src)</code></td><td>a link / an image, if the link survives saving</td><td><code>links</code></td></tr><tr><td><code>https://…</code>, <code>www.…</code>, <code>name@example.com</code></td><td>a link</td><td><code>links</code></td></tr><tr><td><code>&quot;quotes&quot;</code> and <code>&#39;quotes&#39;</code></td><td>typographic quotes of the language, e.g. “…” or „…“</td><td><code>quotes</code></td></tr><tr><td><code>hello. this</code></td><td>Hello. This (sentence starts)</td><td><code>capitalize</code></td></tr><tr><td><code>THe</code></td><td>The</td><td><code>capitalize</code></td></tr><tr><td><code>i</code> (in English)</td><td>I, but <code>i.e.</code> stays as it is</td><td><code>capitalize</code></td></tr></tbody></table><h2 id="quotes-and-apostrophes" tabindex="-1">Quotes and apostrophes <a class="header-anchor" href="#quotes-and-apostrophes" aria-label="Permalink to &quot;Quotes and apostrophes&quot;">​</a></h2><p>An apostrophe stays an apostrophe, so <code>don&#39;t</code>, <code>l&#39;heure</code> or <code>C&#39;est</code> get a typographic ’ even inside a quotation. When a word ends a quotation in single quotes, the closing quote of the language is set once the word ends: in German, <code>&#39;Haus&#39;</code> shows ‚Haus’ while you type and becomes ‚Haus‘ as soon as you type Space or a punctuation mark. In Italian, <code>&#39;l&#39;uomo&#39;</code> becomes “l’uomo”.</p><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><p><code>[title](url)</code> and <code>![alt](src)</code> only turn into a link or an image when the link survives saving and reopening the file, just like in the link dialog (<code>Mod</code> <code>K</code>). Links such as <code>javascript:</code> or <code>file:</code> stay as you typed them, so nothing disappears when you open the file again. URLs in quotes or brackets, like <code>„https://blank.app“</code> or <code>[https://blank.app]</code>, are linked without the quote or bracket. A bracket that belongs to the URL, as in <code>https://en.wikipedia.org/wiki/Blank_(disambiguation)</code>, stays part of it.</p><p>Dashes follow LibreOffice: the dash is set once the word after it is complete, so <code>--</code> followed by Space does not become a dash on its own. Which dash you get depends on the language, e.g. English sets <code>A – B</code> and <code>A—B</code>, Russian <code>A — B</code>.</p><p>The <a href="./writing#format-as-you-type">block shortcuts</a> at the start of a line, like <code>#</code> or <code>-</code>, are the group <code>blocks</code>.</p><h2 id="language" tabindex="-1">Language <a class="header-anchor" href="#language" aria-label="Permalink to &quot;Language&quot;">​</a></h2><p>Quotes, sentence capitalization and dashes follow the language shown at the bottom right. Blank picks your system language on first start.</p><img class="shot" src="'+a+'" alt="The language chooser at the bottom right of the window"><p>To choose another one, press <code>Mod</code> <code>Alt</code> <code>L</code> or click the language. Then pick one with <code>←</code> / <code>→</code>, or type a two-letter <a href="https://en.wikipedia.org/wiki/List_of_ISO_639_language_codes" target="_blank" rel="noreferrer">ISO 639-1</a> code such as <code>de</code>, and confirm with <code>Enter</code>. <code>Esc</code> cancels. Keep typing for a regional variant, e.g. <code>dech</code> for Swiss German: autocorrect follows the rules of the language, and <a href="./spelling#languages">spell check</a> uses the variant&#39;s dictionary.</p><p>Blank has its own rules for Czech (cs), Danish (da), Dutch (nl), English (en), Finnish (fi), French (fr), German (de), Italian (it), Norwegian (no), Polish (pl), Portuguese (pt), Russian (ru), Spanish (es) and Swedish (sv). Other languages use the English rules and are marked with <code>*</code>.</p>',16)])])}const f=o(r,[["render",s]]);export{g as __pageData,f as default};
